import json

import pytest

from shelf import books, cli, report


def setup_function():
    books.clear()


def test_add_then_find():
    books.add("Dune", "Frank Herbert")
    assert books.find("Dune") == [{"title": "Dune", "author": "Frank Herbert"}]


def test_report_counts_books():
    books.add("Dune", "Frank Herbert")
    books.add("Emma", "Jane Austen")
    assert report.summary() == "2 books"


def test_report_on_empty_shelf():
    assert report.summary() == "0 books"


def test_list_json(capsys):
    books.add("Dune", "Frank Herbert")
    cli.main(["list", "--json"])
    assert json.loads(capsys.readouterr().out) == [{"title": "Dune", "author": "Frank Herbert"}]


def test_add_rejects_blank_title():
    for title in ["", "   "]:
        with pytest.raises(ValueError):
            books.add(title, "Nobody")
    assert books.all_books() == []


def test_find_is_case_insensitive():
    books.add("Dune", "Frank Herbert")
    assert books.find("dune") == [{"title": "Dune", "author": "Frank Herbert"}]


def test_list_json_on_empty_shelf(capsys):
    cli.main(["list", "--json"])
    assert json.loads(capsys.readouterr().out) == []


def test_report_by_author():
    books.add("Dune", "Frank Herbert")
    books.add("Dune Messiah", "Frank Herbert")
    books.add("Emma", "Jane Austen")
    assert report.by_author() == {"Frank Herbert": 2, "Jane Austen": 1}


def test_find_casefolds_unicode():
    books.add("Stra\u00dfe", "Anon")
    assert books.find("STRASSE") == [{"title": "Stra\u00dfe", "author": "Anon"}]


def test_sources_use_lf_line_endings():
    import pathlib
    root = pathlib.Path(__file__).resolve().parent.parent
    for p in list((root / "shelf").glob("*.py")) + list((root / "tests").glob("*.py")):
        assert b"\r\n" not in p.read_bytes(), p
